    edge_rows=[r for r in payload["row_marks"] if r["kind"]=="EDGE_CONSISTENCY"]
    parent_counts=defaultdict(int)
    for r in edge_rows: parent_counts[(r["parent_stage"],r["parent_lane"])]+=1
    assert max(parent_counts.values()) >= 2
